-- Contenido inicial del diagnóstico: 10 preguntas por pilar, 4 opciones cada una (puntaje 0–3).
-- Generado con un script; para cambiar el contenido, crear una nueva migración.

create function pg_temp.add_question(p_pillar public.pillar, p_position smallint, p_prompt jsonb, p_options jsonb)
returns void language plpgsql as $$
declare v_question_id uuid;
begin
  insert into public.diagnostic_questions (pillar, position, prompt)
  values (p_pillar, p_position, p_prompt)
  returning id into v_question_id;

  insert into public.diagnostic_options (question_id, position, label, score)
  select v_question_id, (o.ordinality)::smallint, o.value -> 'label', (o.value ->> 'score')::smallint
  from jsonb_array_elements(p_options) with ordinality as o;
end;
$$;

